import { Link, useNavigate } from "react-router-dom";

export default function Dashboard() {
  const navigate = useNavigate();

  const user = JSON.parse(localStorage.getItem("user"));
  const users = JSON.parse(localStorage.getItem("users")) || [];
  const courses = JSON.parse(localStorage.getItem("courses")) || [];

  if (!user) {
    navigate("/login");
    return null;
  }

  const logout = () => {
    localStorage.removeItem("user");
    navigate("/login");
  };

  let cards = [];

  // ROLE BASED DASHBOARD
  if (user.role === "Admin") {
    cards = [
      { title: "👨‍🎓 Students", path: "/students", color: "#3b82f6" },
      { title: "👨‍🏫 Instructors", path: "/instructors", color: "#8b5cf6" },
      { title: "📚 Courses", path: "/courses", color: "#06b6d4" },
      { title: "👤 Profile", path: "/profile", color: "#f59e0b" },
      { title: "📈 Progress", path: "/progress", color: "#22c55e" },
      { title: "⚙️ Settings", path: "/settings", color: "#ef4444" }
    ];
  } 
  else if (user.role === "Instructor") {
    cards = [
      { title: "📚 My Courses", path: "/courses", color: "#8b5cf6" },
      { title: "👨‍🎓 Students", path: "/students", color: "#10b981" },
      { title: "⚙️ Settings", path: "/settings", color: "#ef4444" }
    ];
  } 
  else {
    cards = [
      { title: "👤 Profile", path: "/profile", color: "#3b82f6" },
      { title: "📚 Courses", path: "/courses", color: "#8b5cf6" },
      { title: "📈 Progress", path: "/progress", color: "#22c55e" }
    ];
  }

  return (
    <div style={styles.container}>

      {/* HEADER */}
      <div style={styles.header}>
        <h1>🎯 RBAC Dashboard</h1>
        <h2>Welcome, {user.name}</h2>
        <p>{user.email}</p>

        <h3>
          Role: <span style={{ color: "#22c55e" }}>{user.role}</span>
        </h3>

        <button style={styles.logout} onClick={logout}>
          Logout
        </button>
      </div>

      {/* CARDS */}
      <div style={styles.grid}>
        {cards.map((c, i) => (
          <Link key={i} to={c.path} style={styles.link}>
            <div style={{ ...styles.card, background: c.color }}>
              <h2>{c.title}</h2>
              <p>Open Module →</p>
            </div>
          </Link>
        ))}
      </div>

      {/* STATS (REAL DATA) */}
      <div style={styles.stats}>

        <div style={styles.statBox}>
          <h3>Total Users</h3>
          <p>{users.length}</p>
        </div>

        <div style={styles.statBox}>
          <h3>Students</h3>
          <p>{users.filter(u => u.role === "Student").length}</p>
        </div>

        <div style={styles.statBox}>
          <h3>Instructors</h3>
          <p>{users.filter(u => u.role === "Instructor").length}</p>
        </div>

        <div style={styles.statBox}>
          <h3>Courses</h3>
          <p>{courses.length}</p>
        </div>

      </div>

    </div>
  );
}

/* STYLES */
const styles = {
  container: {
    minHeight: "100vh",
    padding: "40px",
    background: "linear-gradient(135deg,#0f172a,#1e293b,#334155)",
    color: "white"
  },

  header: {
    textAlign: "center",
    marginBottom: "40px"
  },

  logout: {
    marginTop: "15px",
    padding: "10px 20px",
    background: "#ef4444",
    border: "none",
    color: "white",
    borderRadius: "8px",
    cursor: "pointer"
  },

  grid: {
    display: "grid",
    gridTemplateColumns: "repeat(auto-fit,minmax(220px,1fr))",
    gap: "20px"
  },

  card: {
    padding: "25px",
    borderRadius: "15px",
    boxShadow: "0 10px 25px rgba(0,0,0,0.3)",
    cursor: "pointer"
  },

  link: {
    textDecoration: "none",
    color: "white"
  },

  stats: {
    display: "flex",
    justifyContent: "center",
    gap: "20px",
    marginTop: "50px",
    flexWrap: "wrap"
  },

  statBox: {
    background: "#1e293b",
    padding: "20px",
    borderRadius: "12px",
    width: "180px",
    textAlign: "center"
  }
};
